import json
import sys
from collections import Counter

import h5py
import numpy as np


def decode_value(value):
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="replace")
    if isinstance(value, np.bytes_):
        return bytes(value).decode("utf-8", errors="replace")
    if isinstance(value, np.generic):
        return decode_value(value.item())
    return value


def read_member(handle):
    if isinstance(handle, h5py.Dataset):
        return [decode_value(x) for x in handle[...].tolist()]
    if isinstance(handle, h5py.Group):
        keys = set(handle.keys())
        if {"codes", "categories"}.issubset(keys):
            codes = np.asarray(handle["codes"][...])
            categories = [decode_value(x) for x in handle["categories"][...].tolist()]
            return [categories[int(code)] if int(code) >= 0 else None for code in codes]
    raise TypeError("unsupported HDF5 member: " + handle.name)


